css:
* {
    font-family: sans-serif;
    line-height: 1.4;
}

body {
    font-size: 12pt;
    color: #1a1a1a;
    margin: 25mm;
    background: #ffffff;
    line-height: 1.6;
}

/* Company Header Styling */
h3 {
    font-size: 18pt;
    text-align: center;
    color: #1a1a1a;
    margin-bottom: 15pt;
    font-weight: bold;
    letter-spacing: 0.5pt;
    text-transform: uppercase;
}

h4 {
    font-size: 14pt;
    margin-top: 25pt;
    margin-bottom: 10pt;
    color: #1a1a1a;
    font-weight: bold;
    border-bottom: 2pt solid #2c3e50;
    padding-bottom: 5pt;
    letter-spacing: 0.3pt;
}

h5 {
    font-size: 12pt;
    margin-top: 20pt;
    margin-bottom: 8pt;
    color: #2c3e50;
    font-weight: bold;
    letter-spacing: 0.2pt;
}

strong {
    color: #1a1a1a;
    font-weight: bold;
}

p {
    text-align: justify;
    margin-bottom: 10pt;
    line-height: 1.8;
}


/* Signature and Place/Date Tables */
.signature-table,
.place-date-table {
    width: 100%;
    font-size: 10pt;
    margin-top: 30pt;
    border: none;
    box-shadow: none;
}


/* Section and Note Formatting */
.section-heading {
    font-size: 16pt;
    color: #1a1a1a;
    margin-top: 30pt;
    margin-bottom: 15pt;
    font-weight: bold;
    text-align: center;
    text-transform: uppercase;
    letter-spacing: 0.5pt;
    border-bottom: 3pt solid #2c3e50;
    padding-bottom: 10pt;
}

.note-title {
    font-size: 12pt;
    color: #2c3e50;
    font-weight: bold;
    margin-top: 20pt;
    margin-bottom: 10pt;
    border-left: 4pt solid #3498db;
    padding-left: 10pt;
    letter-spacing: 0.2pt;
}

.note-desc {
    font-size: 10pt;
    color: #34495e;
    margin-bottom: 12pt;
    text-align: justify;
    line-height: 1.7;
    text-indent: 20pt;
}

/* Print/PDF Optimizations */
.page-break {
    page-break-before: always;
}

@media print {
    body {
        margin: 20mm;
        font-size: 11pt;
    }

    .page-break {
        display: block;
        page-break-before: always;
    }


    h3, h4, .section-heading {
        page-break-after: avoid;
    }

    .note-title {
        page-break-after: avoid;
    }
}

/* Additional Professional Styling */
.company-header {
    text-align: center;
    margin-bottom: 30pt;
    padding-bottom: 20pt;
    border-bottom: 3pt double #2c3e50;
}

.auditor-section {
    margin-top: 25pt;
    padding: 20pt;
    background: #f8f9fa;
    border-left: 5pt solid #3498db;
    border-radius: 5pt;
}

.signature-line {
    border-top: 1pt solid #2c3e50;
    margin-top: 15pt;
    padding-top: 5pt;
    text-align: center;
    font-weight: bold;
    font-size: 10pt;
}

/* Highlight styling for sections */
.section-highlight {
    background-color: #fff3cd !important;
    border: 2pt solid #ffc107 !important;
    border-radius: 5pt;
    transition: all 0.3s ease;
    animation: highlight-pulse 2s ease-in-out;
}

@keyframes highlight-pulse {
    0% { background-color: #fff3cd; }
    50% { background-color: #ffeaa7; }
    100% { background-color: #fff3cd; }
}

/* Clickable row styling */
.clickable-row {
    cursor: pointer !important;
    transition: background-color 0.2s ease;
}
